<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();
$orgId=saas_require_organization();$db=saas_db();$org=saas_current_organization();$baseUrl=rtrim((string)($config['app']['base_url']??''),'/');
$q=$db->prepare("SELECT t.id,t.name,t.slug,t.start_date,t.status FROM tours t INNER JOIN tour_members tm ON tm.tour_id=t.id WHERE t.organization_id=? AND tm.user_id=? AND tm.status='ACTIVE' ORDER BY t.start_date DESC,t.id DESC");$q->execute([$orgId,saas_user_id()]);$tours=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Public URLs — GoTM</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font-family:Inter,Arial,sans-serif;color:#172033}.wrap{max-width:950px;margin:35px auto;padding:0 16px}.box{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:22px;margin-bottom:15px}.row{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap}.url{background:#f8fafc;padding:9px;border-radius:8px;word-break:break-all;color:#155eef;font-size:13px}.btn{display:inline-block;padding:9px 12px;border:1px solid #d0d5dd;border-radius:9px;font-weight:800;color:#172033;background:#fff}.muted{color:#667085;font-size:13px}.empty{text-align:center;padding:35px}</style></head><body><main class="wrap"><p><a href="tours.php">← Back to tours</a></p><h1>Public URLs</h1><p class="muted">Public pages for your organization's tours.</p><?php if(!$tours):?><section class="box empty">No tours yet. <a class="btn" href="tour_create.php">Create tour</a></section><?php else:foreach($tours as $t):$url=$baseUrl.'/tour/'.rawurlencode((string)$t['slug']);?><section class="box"><div class="row"><div><h2 style="margin:0"><?=saas_h($t['name'])?></h2><p class="muted"><?=saas_h($t['status'])?><?=!empty($t['start_date'])?' · '.saas_h($t['start_date']):''?></p></div><div><a class="btn" href="tour_open.php?id=<?=$t['id']?>">Dashboard</a> <a class="btn" href="tour_settings.php?tour_id=<?=$t['id']?>">Settings</a> <a class="btn" target="_blank" rel="noopener" href="<?=saas_h($url)?>">Open</a></div></div><div class="url" style="margin-top:12px"><?=saas_h($url)?></div></section><?php endforeach;endif;?></main></body></html>